// =====================================================================
// Config & Safety Gate
// Reads every setting from environment variables, validates it and
// computes the effective safety gate. Secrets are NEVER copied into the
// execution data: only "is it set?" booleans leave this node.
// Any unreadable, missing or invalid value falls back to the SAFE default.
// =====================================================================
let envAccessBlocked = false;
const gateWarnings = [];
const configErrors = [];

const readEnv = (key) => {
  try {
    const v = $env[key];
    if (v === undefined || v === null) return undefined;
    const s = String(v).trim();
    return s === '' ? undefined : s;
  } catch (e) {
    envAccessBlocked = true;
    return undefined;
  }
};

const bool = (key, safeDefault) => {
  const v = readEnv(key);
  if (v === undefined) return safeDefault;
  const s = v.toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(s)) return true;
  if (['false', '0', 'no', 'off'].includes(s)) return false;
  gateWarnings.push(`${key}="${v}" is not a boolean; using safe default ${safeDefault}.`);
  return safeDefault;
};

const num = (key, def, min, max) => {
  const v = readEnv(key);
  if (v === undefined) return def;
  const n = Number(v);
  if (!Number.isFinite(n) || n < min || n > max) {
    gateWarnings.push(`${key}="${v}" is outside [${min}, ${max}]; using default ${def}.`);
    return def;
  }
  return n;
};

const str = (key, def) => readEnv(key) ?? def;

// ---- Safety flags (safe by default) --------------------------------
const requestedSandbox = bool('SANDBOX_MODE', true);
const requestedDryRun = bool('DRY_RUN', true);
const pacingUpdatesEnabled = bool('PACING_UPDATES_ENABLED', false);
const sendSlackAlerts = bool('SEND_SLACK_ALERTS', false);
const sendWebhookAlerts = bool('SEND_WEBHOOK_ALERTS', false);

// ---- Secret presence checks (values are never output) --------------
const outboundApiKey = readEnv('OUTBOUND_API_KEY');
const slackWebhookUrl = readEnv('SLACK_ALERT_WEBHOOK_URL');
const alertWebhookUrl = readEnv('ALERT_WEBHOOK_URL');
const hasOutboundApiKey = Boolean(outboundApiKey);
const hasSlackWebhook = Boolean(slackWebhookUrl) && /^https:\/\//i.test(slackWebhookUrl);
const hasAlertWebhook = Boolean(alertWebhookUrl) && /^https:\/\//i.test(alertWebhookUrl);
if (slackWebhookUrl && !hasSlackWebhook) gateWarnings.push('SLACK_ALERT_WEBHOOK_URL must start with https:// — Slack alerts disabled.');
if (alertWebhookUrl && !hasAlertWebhook) gateWarnings.push('ALERT_WEBHOOK_URL must start with https:// — webhook alerts disabled.');

// ---- Outbound platform (non-secret) --------------------------------
const outbound = {
  platform: str('OUTBOUND_PLATFORM', 'generic'),
  apiBaseUrl: str('OUTBOUND_API_BASE_URL', 'https://api.outbound-platform.example.com/v1').replace(/\/+$/, ''),
  mailboxHealthPath: str('OUTBOUND_MAILBOX_HEALTH_PATH', '/mailboxes/health'),
  campaignMetricsPath: str('OUTBOUND_CAMPAIGN_METRICS_PATH', '/campaigns/sequence-metrics'),
  pacingUpdatePath: str('OUTBOUND_PACING_UPDATE_PATH', '/campaigns/{campaign_id}/sequence-delays'),
  campaignIdFilter: (readEnv('OUTBOUND_CAMPAIGN_IDS') || '')
    .split(',').map((s) => s.trim()).filter(Boolean),
  lookbackDays: num('METRICS_LOOKBACK_DAYS', 7, 1, 90),
};

// ---- Thresholds & multipliers --------------------------------------
const thresholds = {
  bounceWarnPct: num('BOUNCE_RATE_WARN_PCT', 2.0, 0, 100),
  bounceThrottlePct: num('BOUNCE_RATE_THROTTLE_PCT', 3.0, 0, 100),
  bounceCriticalPct: num('BOUNCE_RATE_CRITICAL_PCT', 5.0, 0, 100),
  spamWarnPct: num('SPAM_RATE_WARN_PCT', 0.1, 0, 100),
  spamCriticalPct: num('SPAM_RATE_CRITICAL_PCT', 0.3, 0, 100),
  volumeUtilizationWarnPct: num('VOLUME_UTILIZATION_WARN_PCT', 90, 1, 200),
  reputationFloorPct: num('WARMUP_REPUTATION_FLOOR_PCT', 90, 0, 100),
  minMailboxSample: num('MIN_MAILBOX_SAMPLE_SIZE', 50, 0, 100000),
  unsubscribeGuardPct: num('UNSUBSCRIBE_RATE_GUARD_PCT', 1.0, 0, 100),
};

const pacing = {
  minStepDelayDays: num('MIN_STEP_DELAY_DAYS', 2, 0, 60),
  maxStepDelayDays: num('MAX_STEP_DELAY_DAYS', 10, 1, 90),
  maxDelayChangeDaysPerRun: num('MAX_DELAY_CHANGE_DAYS_PER_RUN', 2, 1, 30),
  minStepSampleSize: num('MIN_STEP_SAMPLE_SIZE', 100, 1, 1000000),
  maxCampaignsUpdatedPerRun: num('MAX_CAMPAIGNS_UPDATED_PER_RUN', 25, 1, 1000),
};

const velocity = {
  benchmarkReplyRatePct: num('BENCHMARK_REPLY_RATE_PCT', 2.0, 0.01, 100),
  benchmarkClickRatePct: num('BENCHMARK_CLICK_RATE_PCT', 1.5, 0.01, 100),
  benchmarkHoursToEngagement: num('BENCHMARK_HOURS_TO_ENGAGEMENT', 48, 1, 2000),
  highThreshold: num('VELOCITY_HIGH_THRESHOLD', 1.3, 0, 10),
  sluggishThreshold: num('VELOCITY_SLUGGISH_THRESHOLD', 0.8, 0, 10),
  stalledThreshold: num('VELOCITY_STALLED_THRESHOLD', 0.5, 0, 10),
  compressMultiplier: num('VELOCITY_COMPRESS_MULTIPLIER', 0.75, 0.1, 1),
  expandMultiplier: num('VELOCITY_EXPAND_MULTIPLIER', 1.35, 1, 5),
  stalledMultiplier: num('VELOCITY_STALLED_MULTIPLIER', 1.6, 1, 5),
  shiftAlertPct: num('VELOCITY_SHIFT_ALERT_PCT', 25, 1, 1000),
};

const health = {
  watchMultiplier: num('HEALTH_WATCH_MULTIPLIER', 1.15, 1, 5),
  throttleMultiplier: num('HEALTH_THROTTLE_MULTIPLIER', 1.5, 1, 5),
};

const circuitBreaker = {
  criticalMailboxPct: num('CIRCUIT_BREAKER_CRITICAL_MAILBOX_PCT', 30, 1, 100),
  orgBounceRatePct: num('CIRCUIT_BREAKER_BOUNCE_RATE_PCT', 5.0, 0.1, 100),
};

const alerts = {
  minSeverity: (str('ALERT_MIN_SEVERITY', 'WARNING') || 'WARNING').toUpperCase(),
  maxItemsPerSection: num('ALERT_MAX_ITEMS_PER_SECTION', 8, 1, 25),
};
if (!['INFO', 'WARNING', 'CRITICAL'].includes(alerts.minSeverity)) {
  gateWarnings.push(`ALERT_MIN_SEVERITY="${alerts.minSeverity}" is invalid; using WARNING.`);
  alerts.minSeverity = 'WARNING';
}

// ---- Cross-field validation (any error => no live mutations) -------
if (pacing.minStepDelayDays >= pacing.maxStepDelayDays) configErrors.push('MIN_STEP_DELAY_DAYS must be lower than MAX_STEP_DELAY_DAYS.');
if (!(thresholds.bounceWarnPct < thresholds.bounceThrottlePct && thresholds.bounceThrottlePct < thresholds.bounceCriticalPct)) configErrors.push('Bounce thresholds must satisfy WARN < THROTTLE < CRITICAL.');
if (!(thresholds.spamWarnPct < thresholds.spamCriticalPct)) configErrors.push('Spam thresholds must satisfy WARN < CRITICAL.');
if (!(velocity.stalledThreshold < velocity.sluggishThreshold && velocity.sluggishThreshold < velocity.highThreshold)) configErrors.push('Velocity thresholds must satisfy STALLED < SLUGGISH < HIGH.');
if (!(velocity.stalledMultiplier >= velocity.expandMultiplier)) configErrors.push('VELOCITY_STALLED_MULTIPLIER must be >= VELOCITY_EXPAND_MULTIPLIER.');

// ---- Effective safety gate -----------------------------------------
let sandboxMode = requestedSandbox;
const gateReasons = [];
if (envAccessBlocked) gateReasons.push('Environment access is blocked in this n8n instance (N8N_BLOCK_ENV_ACCESS_IN_NODE). All settings fell back to safe defaults.');
if (!sandboxMode && !hasOutboundApiKey) { sandboxMode = true; gateReasons.push('SANDBOX_MODE=false but OUTBOUND_API_KEY is not set — forced back to sandbox.'); }
if (!sandboxMode && !/^https:\/\//i.test(outbound.apiBaseUrl)) { sandboxMode = true; gateReasons.push('OUTBOUND_API_BASE_URL must use https:// — forced back to sandbox.'); }
if (!sandboxMode && /\.example\.com/i.test(outbound.apiBaseUrl)) { sandboxMode = true; gateReasons.push('OUTBOUND_API_BASE_URL still points at the placeholder example.com host — forced back to sandbox.'); }
if (configErrors.length) gateReasons.push(`Configuration errors found (${configErrors.length}) — live mutations disabled.`);

const dryRun = requestedDryRun || sandboxMode;
const liveMutationsPermitted = !sandboxMode && !requestedDryRun && pacingUpdatesEnabled && configErrors.length === 0;
if (!pacingUpdatesEnabled) gateReasons.push('PACING_UPDATES_ENABLED=false — pacing changes are previewed only.');
if (requestedDryRun) gateReasons.push('DRY_RUN=true — no writes to the outbound platform.');
if (sandboxMode) gateReasons.push('SANDBOX_MODE=true — mock fixture data, zero network calls.');

const slackAlertsPermitted = sendSlackAlerts && !sandboxMode && hasSlackWebhook;
const webhookAlertsPermitted = sendWebhookAlerts && !sandboxMode && hasAlertWebhook;

// ---- Run metadata --------------------------------------------------
const startedAt = new Date().toISOString();
let trigger = 'manual';
try { if ($('Daily 07:00 UTC Schedule').isExecuted) trigger = 'schedule'; } catch (e) { /* manual */ }
const runId = `pacing-${startedAt.slice(0, 10).replace(/-/g, '')}-${Math.random().toString(36).slice(2, 8)}`;

let mode = 'SANDBOX';
if (!sandboxMode) mode = liveMutationsPermitted ? 'LIVE' : 'DRY_RUN';

return [{
  json: {
    runId,
    startedAt,
    trigger,
    workflow: 'n8n-outbound-sequence-step-pacing-optimization-engine',
    workflowVersion: '1.0.0',
    config: { outbound, thresholds, pacing, velocity, health, circuitBreaker, alerts },
    gate: {
      mode,
      sandboxMode,
      dryRun,
      requested: { sandboxMode: requestedSandbox, dryRun: requestedDryRun, pacingUpdatesEnabled, sendSlackAlerts, sendWebhookAlerts },
      liveMutationsPermitted,
      slackAlertsPermitted,
      webhookAlertsPermitted,
      secretsPresent: { outboundApiKey: hasOutboundApiKey, slackWebhook: hasSlackWebhook, alertWebhook: hasAlertWebhook },
      envAccessBlocked,
      reasons: gateReasons,
      warnings: gateWarnings,
      configErrors,
    },
  },
}];

// =====================================================================
// Normalize Live Metrics
// Maps the outbound platform (or adapter) responses onto the canonical
// schema used by the optimization engine. Accepts common field aliases so
// a thin adapter, or a platform that already returns similar fields,
// can plug in. Prospect-level PII is never carried forward.
// =====================================================================
const ctx = $('Config & Safety Gate').first().json;
const mbItems = $('Fetch Mailbox Health (Live)').all();
const cpItems = $('Fetch Campaign Metrics (Live)').all();

const collect = (items, key) => items.flatMap((i) => {
  const j = i.json || {};
  if (Array.isArray(j[key])) return j[key];
  if (j.data && Array.isArray(j.data[key])) return j.data[key];
  if (Array.isArray(j.data)) return j.data;
  if (Array.isArray(j.items)) return j.items;
  return Object.keys(j).length ? [j] : [];
});

const first = (obj, keys, def = undefined) => {
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return def;
};
const n = (v, d = 0) => { const x = Number(v); return Number.isFinite(x) ? x : d; };
const nOrNull = (v) => { const x = Number(v); return v === null || v === undefined || v === '' || !Number.isFinite(x) ? null : x; };

const mailboxes = collect(mbItems, 'mailboxes').map((m) => {
  const out = {
    mailbox_id: String(first(m, ['mailbox_id', 'id', 'email_account_id', 'account_id'], 'unknown')),
    sending_domain: first(m, ['sending_domain', 'domain'], null) || String(first(m, ['email', 'from_email'], '')).split('@')[1] || null,
    provider: first(m, ['provider', 'type', 'esp'], 'unknown'),
    status: String(first(m, ['status', 'state'], 'active')).toLowerCase(),
    daily_limit: n(first(m, ['daily_limit', 'message_per_day', 'max_daily_sends'])),
    daily_volume_avg_7d: n(first(m, ['daily_volume_avg_7d', 'daily_sent_avg', 'avg_daily_sent'])),
    sent_7d: n(first(m, ['sent_7d', 'sent', 'sent_count'])),
    warmup_reputation_pct: nOrNull(first(m, ['warmup_reputation_pct', 'warmup_reputation', 'reputation'])),
  };
  const bounceRate = nOrNull(first(m, ['bounce_rate_pct', 'bounce_rate']));
  const spamRate = nOrNull(first(m, ['spam_complaint_rate_pct', 'spam_rate', 'complaint_rate']));
  if (bounceRate !== null) out.bounce_rate_pct = bounceRate; else out.bounces_7d = n(first(m, ['bounces_7d', 'bounced', 'bounce_count']));
  if (spamRate !== null) out.spam_complaint_rate_pct = spamRate; else out.spam_complaints_7d = n(first(m, ['spam_complaints_7d', 'spam_count', 'complaints']));
  return out;
});

const campaigns = collect(cpItems, 'campaigns').map((c) => ({
  campaign_id: String(first(c, ['campaign_id', 'id'], 'unknown')),
  name: String(first(c, ['name', 'campaign_name'], 'Unnamed campaign')),
  status: String(first(c, ['status', 'state'], 'unknown')).toLowerCase(),
  segment: first(c, ['segment', 'list_name', 'tag'], null),
  mailbox_ids: (first(c, ['mailbox_ids', 'email_account_ids'], []) || []).map(String),
  active_prospects: n(first(c, ['active_prospects', 'active_leads', 'in_progress'])),
  baseline_velocity_index_30d: nOrNull(first(c, ['baseline_velocity_index_30d', 'baseline_velocity'])),
  steps: (first(c, ['steps', 'sequences', 'sequence_steps'], []) || []).map((s) => ({
    step_number: n(first(s, ['step_number', 'seq_number', 'step', 'order'])),
    delay_days: n(first(s, ['delay_days', 'delay_in_days', 'wait_days'])),
    sent: n(first(s, ['sent', 'sent_count'])),
    clicks: n(first(s, ['clicks', 'click_count', 'unique_clicks'])),
    replies: n(first(s, ['replies', 'reply_count'])),
    unsubscribes: n(first(s, ['unsubscribes', 'unsubscribed', 'opt_outs'])),
    median_hours_to_engagement: nOrNull(first(s, ['median_hours_to_engagement', 'median_reply_hours'])),
  })),
}));

if (!mailboxes.length || !campaigns.length) {
  throw new Error(`Live metrics incomplete (mailboxes=${mailboxes.length}, campaigns=${campaigns.length}). Halting before any pacing decision.`);
}

return [{
  json: {
    ...ctx,
    dataSource: 'LIVE_API',
    metrics: {
      fixture_meta: { synthetic: false, as_of: new Date().toISOString(), lookback_window_days: ctx.config.outbound.lookbackDays, platform: ctx.config.outbound.platform },
      mailboxes,
      campaigns,
      prospect_engagement_events: [],
    },
  },
}];

// =====================================================================
// Mailbox Health & Pacing Optimization Engine
// 1. Scores each mailbox (bounce, spam, volume utilization, reputation).
// 2. Rolls mailbox health up to each campaign (send-weighted).
// 3. Computes engagement velocity per step and proposes new step gaps.
// 4. Enforces guardrails: min/max bounds, max change per run,
//    no compression on unhealthy campaigns, per-run update cap and a
//    global circuit breaker for mass high-bounce events.
// Output: one plan item. No prospect identifiers leave this node.
// =====================================================================
const ctx = $input.first().json;
const { config: cfg, gate } = ctx;
const T = cfg.thresholds;
const P = cfg.pacing;
const V = cfg.velocity;
const H = cfg.health;
const CB = cfg.circuitBreaker;

const metrics = ctx.metrics || {};
const mailboxesIn = Array.isArray(metrics.mailboxes) ? metrics.mailboxes : [];
const campaignsIn = Array.isArray(metrics.campaigns) ? metrics.campaigns : [];
const events = Array.isArray(metrics.prospect_engagement_events) ? metrics.prospect_engagement_events : [];

const num = (v, d = 0) => { const x = Number(v); return Number.isFinite(x) ? x : d; };
const round = (v, p = 2) => Math.round(v * 10 ** p) / 10 ** p;
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const pct = (part, whole) => (whole > 0 ? (part / whole) * 100 : 0);
const median = (arr) => {
  if (!arr.length) return null;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};
const RANK = { HEALTHY: 0, WATCH: 1, THROTTLE: 2, CRITICAL: 3 };
const TIERS = ['HEALTHY', 'WATCH', 'THROTTLE', 'CRITICAL'];
const worse = (...tiers) => TIERS[Math.max(...tiers.map((t) => RANK[t] ?? 0))];
const tierFromScore = (s) => (s >= 80 ? 'HEALTHY' : s >= 60 ? 'WATCH' : s >= 40 ? 'THROTTLE' : 'CRITICAL');

// ---------------------------------------------------------------------
// 1. Mailbox health
// ---------------------------------------------------------------------
function bouncePenalty(b) {
  if (b >= T.bounceCriticalPct) return 70;
  if (b >= T.bounceThrottlePct) return 30 + ((b - T.bounceThrottlePct) / (T.bounceCriticalPct - T.bounceThrottlePct)) * 30;
  if (b >= T.bounceWarnPct) return 10 + ((b - T.bounceWarnPct) / (T.bounceThrottlePct - T.bounceWarnPct)) * 20;
  return (b / T.bounceWarnPct) * 10;
}
function spamPenalty(s) {
  if (s >= T.spamCriticalPct) return 70;
  if (s >= T.spamWarnPct) return 10 + ((s - T.spamWarnPct) / (T.spamCriticalPct - T.spamWarnPct)) * 40;
  return (s / T.spamWarnPct) * 10;
}

const mailboxes = mailboxesIn.map((m) => {
  const sent = num(m.sent_7d);
  const bounce = m.bounce_rate_pct != null ? num(m.bounce_rate_pct) : pct(num(m.bounces_7d), sent);
  const spam = m.spam_complaint_rate_pct != null ? num(m.spam_complaint_rate_pct) : pct(num(m.spam_complaints_7d), sent);
  const limit = num(m.daily_limit);
  const util = limit > 0 ? pct(num(m.daily_volume_avg_7d), limit) : 0;
  const rep = m.warmup_reputation_pct != null ? num(m.warmup_reputation_pct, 100) : 100;
  const status = String(m.status || 'active').toLowerCase();
  const flags = [];

  const penalties = {
    bounce: bouncePenalty(bounce),
    spam: spamPenalty(spam),
    volume: util > T.volumeUtilizationWarnPct ? clamp(((util - T.volumeUtilizationWarnPct) / Math.max(1, 100 - T.volumeUtilizationWarnPct)) * 10, 0, 15) : 0,
    reputation: rep < T.reputationFloorPct ? clamp((T.reputationFloorPct - rep) * 0.5, 0, 25) : 0,
  };
  const score = clamp(100 - Object.values(penalties).reduce((a, b) => a + b, 0), 0, 100);

  let hardTier = 'HEALTHY';
  if (bounce >= T.bounceCriticalPct) { hardTier = 'CRITICAL'; flags.push(`Bounce ${round(bounce)}% >= critical cap ${T.bounceCriticalPct}%`); }
  else if (bounce >= T.bounceThrottlePct) { hardTier = 'THROTTLE'; flags.push(`Bounce ${round(bounce)}% >= throttle cap ${T.bounceThrottlePct}%`); }
  else if (bounce >= T.bounceWarnPct) { hardTier = 'WATCH'; flags.push(`Bounce ${round(bounce)}% >= warn level ${T.bounceWarnPct}%`); }
  if (spam >= T.spamCriticalPct) { hardTier = 'CRITICAL'; flags.push(`Spam complaints ${round(spam, 3)}% >= critical cap ${T.spamCriticalPct}%`); }
  else if (spam >= T.spamWarnPct) { hardTier = worse(hardTier, 'WATCH'); flags.push(`Spam complaints ${round(spam, 3)}% >= warn level ${T.spamWarnPct}%`); }
  if (util > T.volumeUtilizationWarnPct) flags.push(`Volume at ${round(util, 1)}% of daily limit`);
  if (rep < T.reputationFloorPct) flags.push(`Warm-up reputation ${rep}% below floor ${T.reputationFloorPct}%`);
  const lowSample = sent < T.minMailboxSample;
  if (lowSample) flags.push(`Low sample (${sent} sends) — rates are noisy`);

  const active = status === 'active';
  if (!active) flags.push(`Mailbox status "${status}" — excluded from campaign health weighting`);

  return {
    mailbox_id: String(m.mailbox_id),
    sending_domain: m.sending_domain || null,
    provider: m.provider || 'unknown',
    status,
    active,
    sent_7d: sent,
    bounce_rate_pct: round(bounce),
    spam_complaint_rate_pct: round(spam, 3),
    volume_utilization_pct: round(util, 1),
    warmup_reputation_pct: rep,
    health_score: round(score, 1),
    penalties: Object.fromEntries(Object.entries(penalties).map(([k, v]) => [k, round(v, 1)])),
    tier: worse(tierFromScore(score), hardTier),
    low_sample: lowSample,
    flags,
  };
});
const mailboxById = Object.fromEntries(mailboxes.map((m) => [m.mailbox_id, m]));
const activeMailboxes = mailboxes.filter((m) => m.active);

// ---------------------------------------------------------------------
// 2. Global circuit breaker
// ---------------------------------------------------------------------
const totalSent = activeMailboxes.reduce((a, m) => a + m.sent_7d, 0);
const orgBounceRate = totalSent > 0 ? activeMailboxes.reduce((a, m) => a + m.bounce_rate_pct * m.sent_7d, 0) / totalSent : 0;
const criticalCount = activeMailboxes.filter((m) => m.tier === 'CRITICAL').length;
const criticalPct = activeMailboxes.length ? pct(criticalCount, activeMailboxes.length) : 0;
const cbReasons = [];
if (!activeMailboxes.length) cbReasons.push('DATA_ANOMALY: no active mailboxes in the dataset');
if (!campaignsIn.length) cbReasons.push('DATA_ANOMALY: no campaigns in the dataset');
if (criticalPct >= CB.criticalMailboxPct) cbReasons.push(`${round(criticalPct, 1)}% of active mailboxes are CRITICAL (breaker at ${CB.criticalMailboxPct}%)`);
if (orgBounceRate >= CB.orgBounceRatePct) cbReasons.push(`Org-wide bounce rate ${round(orgBounceRate)}% (breaker at ${CB.orgBounceRatePct}%)`);
const circuitBreaker = {
  tripped: cbReasons.length > 0,
  reasons: cbReasons,
  org_bounce_rate_pct: round(orgBounceRate),
  critical_mailbox_pct: round(criticalPct, 1),
  critical_mailboxes: criticalCount,
  active_mailboxes: activeMailboxes.length,
  recommended_action: cbReasons.length ? 'Freeze automated pacing changes, pause affected campaigns manually, and investigate list quality and DNS/authentication before resuming.' : null,
};

// ---------------------------------------------------------------------
// 3. Velocity helpers
// ---------------------------------------------------------------------
const VELOCITY_MULT = { HIGH: V.compressMultiplier, NORMAL: 1, SLUGGISH: V.expandMultiplier, STALLED: V.stalledMultiplier, INSUFFICIENT_DATA: 1 };
const HEALTH_MULT = { HEALTHY: 1, WATCH: H.watchMultiplier, THROTTLE: H.throttleMultiplier };

function stepVelocity(campaignId, step) {
  const sent = num(step.sent);
  const replyRate = pct(num(step.replies), sent);
  const clickRate = pct(num(step.clicks), sent);
  const unsubRate = pct(num(step.unsubscribes), sent);
  const evHours = events
    .filter((e) => String(e.campaign_id) === String(campaignId) && num(e.step_number) === num(step.step_number) && ['reply', 'click'].includes(e.event))
    .map((e) => num(e.hours_since_send, NaN)).filter(Number.isFinite);
  let hours = null; let hoursSource = 'none';
  if (evHours.length >= 5) { hours = median(evHours); hoursSource = `events(n=${evHours.length})`; }
  else if (step.median_hours_to_engagement != null && num(step.median_hours_to_engagement) > 0) { hours = num(step.median_hours_to_engagement); hoursSource = 'step_metric'; }

  const replyComp = Math.min(replyRate / V.benchmarkReplyRatePct, 3);
  const clickComp = Math.min(clickRate / V.benchmarkClickRatePct, 3);
  const timeComp = hours ? Math.min(V.benchmarkHoursToEngagement / hours, 3) : 1;
  const index = 0.6 * replyComp + 0.25 * clickComp + 0.15 * timeComp;

  let band;
  if (sent < P.minStepSampleSize) band = 'INSUFFICIENT_DATA';
  else if (index >= V.highThreshold) band = 'HIGH';
  else if (index >= V.sluggishThreshold) band = 'NORMAL';
  else if (index >= V.stalledThreshold) band = 'SLUGGISH';
  else band = 'STALLED';

  return {
    sent,
    reply_rate_pct: round(replyRate),
    click_rate_pct: round(clickRate),
    unsubscribe_rate_pct: round(unsubRate),
    median_hours_to_engagement: hours != null ? round(hours, 1) : null,
    hours_source: hoursSource,
    velocity_index: round(index, 3),
    band,
  };
}

// ---------------------------------------------------------------------
// 4. Campaign evaluation
// ---------------------------------------------------------------------
const filter = cfg.outbound.campaignIdFilter || [];
const campaigns = campaignsIn
  .filter((c) => !filter.length || filter.includes(String(c.campaign_id)))
  .map((c) => {
    const campaignId = String(c.campaign_id);
    const status = String(c.status || 'unknown').toLowerCase();
    const base = { campaign_id: campaignId, name: c.name || campaignId, segment: c.segment || null, status, active_prospects: num(c.active_prospects) };

    if (status !== 'active') {
      return { ...base, decision: 'SKIPPED_INACTIVE', health: null, velocity: null, adjustments: [], notes: [`Campaign status is "${status}" — not evaluated.`] };
    }

    // Campaign health (send-weighted across active mailboxes)
    const mbs = (c.mailbox_ids || []).map((id) => mailboxById[String(id)]).filter((m) => m && m.active);
    const notes = [];
    let campaignHealth;
    if (!mbs.length) {
      campaignHealth = { score: null, tier: 'WATCH', worst_mailbox_tier: null, critical_send_share_pct: 0, mailbox_ids: [] };
      notes.push('No active mailbox health data for this campaign — compression disabled.');
    } else {
      const w = mbs.reduce((a, m) => a + Math.max(1, m.sent_7d), 0);
      const score = mbs.reduce((a, m) => a + m.health_score * Math.max(1, m.sent_7d), 0) / w;
      const worst = worse(...mbs.map((m) => m.tier));
      const critShare = mbs.filter((m) => m.tier === 'CRITICAL').reduce((a, m) => a + Math.max(1, m.sent_7d), 0) / w;
      const inherited = worst === 'CRITICAL' ? 'THROTTLE' : worst === 'THROTTLE' ? 'WATCH' : 'HEALTHY';
      const tier = worse(tierFromScore(score), inherited, critShare >= 0.5 ? 'CRITICAL' : 'HEALTHY');
      campaignHealth = { score: round(score, 1), tier, worst_mailbox_tier: worst, critical_send_share_pct: round(critShare * 100, 1), mailbox_ids: mbs.map((m) => m.mailbox_id) };
      const atRisk = mbs.filter((m) => m.tier !== 'HEALTHY').map((m) => `${m.mailbox_id} (${m.tier})`);
      if (atRisk.length) notes.push(`At-risk mailboxes: ${atRisk.join(', ')}`);
    }

    // Steps and transitions
    const steps = [...(c.steps || [])].sort((a, b) => num(a.step_number) - num(b.step_number));
    const stepVel = steps.map((s) => ({ step_number: num(s.step_number), ...stepVelocity(campaignId, s) }));
    const adjustments = [];
    for (let i = 1; i < steps.length; i++) {
      const prev = stepVel[i - 1];
      const target = steps[i];
      const current = num(target.delay_days);
      const reasons = [];
      let band = prev.band;

      if (band === 'HIGH' && prev.unsubscribe_rate_pct >= T.unsubscribeGuardPct) {
        band = 'NORMAL';
        reasons.push(`Unsubscribe rate ${prev.unsubscribe_rate_pct}% >= guard ${T.unsubscribeGuardPct}% — compression cancelled`);
      }
      let vMult = VELOCITY_MULT[band];
      if (vMult < 1 && campaignHealth.tier !== 'HEALTHY') { vMult = 1; reasons.push(`Compression blocked: campaign health is ${campaignHealth.tier}`); }
      if (vMult < 1 && circuitBreaker.tripped) { vMult = 1; reasons.push('Compression blocked: circuit breaker tripped'); }
      if (band === 'INSUFFICIENT_DATA') reasons.push(`Step ${prev.step_number} has ${prev.sent} sends (< ${P.minStepSampleSize}) — velocity held neutral`);
      if (band === 'HIGH' && vMult < 1) reasons.push(`High velocity on step ${prev.step_number} (index ${prev.velocity_index}) — tighten gap`);
      if (band === 'SLUGGISH') reasons.push(`Sluggish engagement on step ${prev.step_number} (index ${prev.velocity_index}) — extend gap`);
      if (band === 'STALLED') reasons.push(`Stalled engagement on step ${prev.step_number} (index ${prev.velocity_index}) — extend gap`);

      let proposed;
      let hMult = 1;
      if (campaignHealth.tier === 'CRITICAL') {
        proposed = P.maxStepDelayDays;
        reasons.push(`Campaign health CRITICAL — emergency expansion to max delay ${P.maxStepDelayDays}d (pause recommended)`);
      } else {
        hMult = HEALTH_MULT[campaignHealth.tier] ?? 1;
        if (hMult > 1) reasons.push(`Health ${campaignHealth.tier} — throttle multiplier x${hMult}`);
        const raw = Math.round(current * vMult * hMult);
        proposed = clamp(raw, P.minStepDelayDays, P.maxStepDelayDays);
        if (proposed !== raw) reasons.push(`Clamped to bounds [${P.minStepDelayDays}d, ${P.maxStepDelayDays}d]`);
        if (Math.abs(proposed - current) > P.maxDelayChangeDaysPerRun) {
          proposed = current + Math.sign(proposed - current) * P.maxDelayChangeDaysPerRun;
          proposed = clamp(proposed, P.minStepDelayDays, P.maxStepDelayDays);
          reasons.push(`Change limited to ${P.maxDelayChangeDaysPerRun}d per run`);
        }
      }
      if (current < P.minStepDelayDays || current > P.maxStepDelayDays) reasons.push(`Current delay ${current}d was outside bounds — enforced`);

      const delta = proposed - current;
      adjustments.push({
        from_step: prev.step_number,
        to_step: num(target.step_number),
        current_delay_days: current,
        proposed_delay_days: proposed,
        delta_days: delta,
        direction: delta < 0 ? 'COMPRESS' : delta > 0 ? 'EXPAND' : 'HOLD',
        velocity_band: band,
        velocity_index: prev.velocity_index,
        velocity_multiplier: vMult,
        health_multiplier: campaignHealth.tier === 'CRITICAL' ? null : hMult,
        reasons: reasons.length ? reasons : ['Within normal range — no change'],
      });
    }

    // Campaign-level velocity & shift vs baseline
    const sampled = stepVel.filter((s) => s.band !== 'INSUFFICIENT_DATA');
    const sw = sampled.reduce((a, s) => a + s.sent, 0);
    const campIndex = sw > 0 ? sampled.reduce((a, s) => a + s.velocity_index * s.sent, 0) / sw : null;
    const baseline = c.baseline_velocity_index_30d != null ? num(c.baseline_velocity_index_30d) : null;
    const shiftPct = campIndex != null && baseline ? ((campIndex - baseline) / baseline) * 100 : null;
    const campBand = campIndex == null ? 'INSUFFICIENT_DATA' : campIndex >= V.highThreshold ? 'HIGH' : campIndex >= V.sluggishThreshold ? 'NORMAL' : campIndex >= V.stalledThreshold ? 'SLUGGISH' : 'STALLED';

    const changed = adjustments.some((a) => a.delta_days !== 0);
    return {
      ...base,
      decision: changed ? 'UPDATE' : 'NO_CHANGE',
      priority: (RANK[campaignHealth.tier] ?? 0) * 100 + adjustments.reduce((a, x) => a + Math.abs(x.delta_days), 0),
      health: campaignHealth,
      velocity: {
        index: campIndex != null ? round(campIndex, 3) : null,
        band: campBand,
        baseline_index_30d: baseline,
        shift_pct: shiftPct != null ? round(shiftPct, 1) : null,
        significant_shift: shiftPct != null && Math.abs(shiftPct) >= V.shiftAlertPct,
        steps: stepVel,
      },
      adjustments,
      notes,
    };
  });

// ---------------------------------------------------------------------
// 5. Run-level guardrails: circuit breaker + per-run update cap
// ---------------------------------------------------------------------
const toUpdate = campaigns.filter((c) => c.decision === 'UPDATE').sort((a, b) => b.priority - a.priority);
toUpdate.forEach((c, idx) => {
  if (circuitBreaker.tripped) { c.decision = 'BLOCKED_CIRCUIT_BREAKER'; c.notes.push('Circuit breaker tripped — change kept as a recommendation only.'); }
  else if (idx >= P.maxCampaignsUpdatedPerRun) { c.decision = 'DEFERRED_RATE_LIMIT'; c.notes.push(`Per-run cap of ${P.maxCampaignsUpdatedPerRun} campaigns reached — deferred to next run.`); }
});

const allAdj = campaigns.flatMap((c) => c.adjustments.map((a) => ({ ...a, campaign_id: c.campaign_id })));
const stats = {
  mailboxes_evaluated: mailboxes.length,
  mailboxes_by_tier: Object.fromEntries(TIERS.map((t) => [t, mailboxes.filter((m) => m.tier === t).length])),
  campaigns_evaluated: campaigns.filter((c) => c.decision !== 'SKIPPED_INACTIVE').length,
  campaigns_skipped: campaigns.filter((c) => c.decision === 'SKIPPED_INACTIVE').length,
  campaigns_with_changes: campaigns.filter((c) => ['UPDATE', 'BLOCKED_CIRCUIT_BREAKER', 'DEFERRED_RATE_LIMIT'].includes(c.decision)).length,
  campaigns_queued_for_update: campaigns.filter((c) => c.decision === 'UPDATE').length,
  step_gaps_evaluated: allAdj.length,
  step_gaps_compressed: allAdj.filter((a) => a.direction === 'COMPRESS').length,
  step_gaps_expanded: allAdj.filter((a) => a.direction === 'EXPAND').length,
  step_gaps_held: allAdj.filter((a) => a.direction === 'HOLD').length,
  significant_velocity_shifts: campaigns.filter((c) => c.velocity && c.velocity.significant_shift).length,
};

return [{
  json: {
    runId: ctx.runId,
    startedAt: ctx.startedAt,
    trigger: ctx.trigger,
    workflow: ctx.workflow,
    workflowVersion: ctx.workflowVersion,
    dataSource: ctx.dataSource,
    dataAsOf: metrics.fixture_meta ? metrics.fixture_meta.as_of : null,
    config: cfg,
    gate,
    circuitBreaker,
    stats,
    mailboxes,
    campaigns,
    evaluatedAt: new Date().toISOString(),
  },
}];

// =====================================================================
// Build Pacing Update Payloads
// Turns every campaign with decision=UPDATE into one batch payload that
// sets the step-to-step delays in the outbound engine. Payloads are
// always built (for preview & audit); whether they are SENT is decided
// by liveUpdateAllowed, which needs every safety flag to agree.
// =====================================================================
const plan = $input.first().json;
const { gate, config: cfg } = plan;

// FNV-1a 32-bit hash: deterministic idempotency keys without crypto.
const fnv1a = (s) => {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
};
const runDate = String(plan.startedAt).slice(0, 10);

const payloads = plan.campaigns
  .filter((c) => c.decision === 'UPDATE' || c.decision === 'BLOCKED_CIRCUIT_BREAKER' || c.decision === 'DEFERRED_RATE_LIMIT')
  .map((c) => {
    const changes = c.adjustments.filter((a) => a.delta_days !== 0);
    const sequenceDelays = changes.map((a) => ({
      step_number: a.to_step,
      delay_in_days: a.proposed_delay_days,
      previous_delay_in_days: a.current_delay_days,
    }));
    const fingerprint = `${c.campaign_id}|${runDate}|${sequenceDelays.map((d) => `${d.step_number}:${d.delay_in_days}`).join(',')}`;
    return {
      campaign_id: c.campaign_id,
      campaign_name: c.name,
      decision: c.decision,
      idempotency_key: `pacing-${c.campaign_id}-${fnv1a(fingerprint)}`,
      body: {
        campaign_id: c.campaign_id,
        sequence_delays: sequenceDelays,
        change_summary: changes.map((a) => `Step ${a.from_step}->${a.to_step}: ${a.current_delay_days}d -> ${a.proposed_delay_days}d (${a.direction}, ${a.velocity_band})`),
        health_tier: c.health ? c.health.tier : null,
        source: 'n8n-outbound-sequence-step-pacing-optimization-engine',
        run_id: plan.runId,
        requested_at: new Date().toISOString(),
      },
    };
  });

const queued = payloads.filter((p) => p.decision === 'UPDATE');
const liveUpdateAllowed = gate.liveMutationsPermitted === true
  && gate.sandboxMode === false
  && gate.dryRun === false
  && plan.circuitBreaker.tripped === false
  && queued.length > 0;

let deliveryMode;
if (gate.sandboxMode) deliveryMode = 'SANDBOX_PREVIEW';
else if (plan.circuitBreaker.tripped) deliveryMode = 'BLOCKED_CIRCUIT_BREAKER';
else if (gate.configErrors && gate.configErrors.length) deliveryMode = 'BLOCKED_CONFIG_INVALID';
else if (gate.requested.dryRun) deliveryMode = 'DRY_RUN_PREVIEW';
else if (!gate.requested.pacingUpdatesEnabled) deliveryMode = 'UPDATES_DISABLED_PREVIEW';
else if (!queued.length) deliveryMode = 'NOTHING_TO_UPDATE';
else deliveryMode = 'LIVE';

const endpointTemplate = `${cfg.outbound.apiBaseUrl}${cfg.outbound.pacingUpdatePath}`;

return [{
  json: {
    ...plan,
    pacingUpdate: {
      liveUpdateAllowed,
      deliveryMode,
      endpointTemplate,
      payloadCount: payloads.length,
      queuedCount: queued.length,
      payloads,
    },
  },
}];

// =====================================================================
// Split Pacing Payloads (live branch only)
// Second, independent safety check: refuses to emit anything unless every
// gate flag still allows live writes. One output item per campaign.
// =====================================================================
const plan = $input.first().json;
const g = plan.gate;
const pu = plan.pacingUpdate;

if (!(pu.liveUpdateAllowed === true && g.liveMutationsPermitted === true && g.sandboxMode === false && g.dryRun === false && plan.circuitBreaker.tripped === false)) {
  throw new Error('Safety interlock: live pacing update branch reached without full authorization. No requests were sent.');
}

return pu.payloads
  .filter((p) => p.decision === 'UPDATE')
  .map((p) => ({
    json: {
      campaign_id: p.campaign_id,
      idempotency_key: p.idempotency_key,
      url: pu.endpointTemplate.replace('{campaign_id}', encodeURIComponent(p.campaign_id)),
      body: p.body,
    },
  }));

// =====================================================================
// Collect Update Results (live branch)
// Pairs each HTTP response with its campaign and records APPLIED/FAILED.
// =====================================================================
const plan = $('Build Pacing Update Payloads').first().json;
const sentItems = $('Split Pacing Payloads').all();
const responses = $input.all();

const results = responses.map((r, i) => {
  const idx = r.pairedItem && typeof r.pairedItem.item === 'number' ? r.pairedItem.item : i;
  const req = (sentItems[idx] || sentItems[i] || { json: {} }).json;
  const j = r.json || {};
  const status = Number(j.statusCode);
  const ok = !j.error && (Number.isFinite(status) ? status >= 200 && status < 300 : true);
  const errMsg = j.error ? String(j.error.message || j.error).slice(0, 300) : null;
  return {
    campaign_id: req.campaign_id,
    idempotency_key: req.idempotency_key,
    status: ok ? 'APPLIED' : 'FAILED',
    http_status: Number.isFinite(status) ? status : null,
    error: ok ? null : (errMsg || `HTTP ${status}`),
  };
});

// Campaigns that were not sent (deferred / blocked) are still recorded.
const sentIds = new Set(results.map((r) => r.campaign_id));
for (const p of plan.pacingUpdate.payloads) {
  if (!sentIds.has(p.campaign_id)) results.push({ campaign_id: p.campaign_id, idempotency_key: p.idempotency_key, status: p.decision, http_status: null, error: null });
}

return [{
  json: {
    ...plan,
    updateResults: results,
    updateSummary: {
      mode: 'LIVE',
      applied: results.filter((r) => r.status === 'APPLIED').length,
      failed: results.filter((r) => r.status === 'FAILED').length,
      previewed: 0,
    },
  },
}];

// =====================================================================
// Dry-Run Pacing Preview
// Records what WOULD have been sent. No external calls on this branch.
// =====================================================================
const plan = $input.first().json;
const mode = plan.pacingUpdate.deliveryMode;

const results = plan.pacingUpdate.payloads.map((p) => ({
  campaign_id: p.campaign_id,
  idempotency_key: p.idempotency_key,
  status: p.decision === 'UPDATE' ? mode : p.decision,
  http_status: null,
  error: null,
  would_send: p.decision === 'UPDATE' ? { method: 'POST', url: plan.pacingUpdate.endpointTemplate.replace('{campaign_id}', p.campaign_id), body: p.body } : null,
}));

return [{
  json: {
    ...plan,
    updateResults: results,
    updateSummary: {
      mode,
      applied: 0,
      failed: 0,
      previewed: results.filter((r) => r.status === mode).length,
    },
  },
}];

// =====================================================================
// Build RevOps Alerts
// Formats a Slack Block Kit message plus a compact JSON webhook event.
// Alerts carry mailbox IDs and sending domains only — never mailbox
// addresses or prospect data.
// =====================================================================
const run = $input.first().json;
const { gate, circuitBreaker: cb, stats, config: cfg } = run;
const maxItems = cfg.alerts.maxItemsPerSection;
const SEV_RANK = { INFO: 0, WARNING: 1, CRITICAL: 2 };

const truncate = (s, max = 2900) => (s.length > max ? `${s.slice(0, max - 20)}\n_…truncated_` : s);
const tierIcon = { HEALTHY: ':large_green_circle:', WATCH: ':large_yellow_circle:', THROTTLE: ':large_orange_circle:', CRITICAL: ':red_circle:' };
const dirIcon = { COMPRESS: ':arrow_down:', EXPAND: ':arrow_up:', HOLD: ':left_right_arrow:' };

const atRisk = run.mailboxes.filter((m) => m.tier !== 'HEALTHY').sort((a, b) => a.health_score - b.health_score);
const changedCampaigns = run.campaigns.filter((c) => c.adjustments && c.adjustments.some((a) => a.delta_days !== 0));
const shifts = run.campaigns.filter((c) => c.velocity && c.velocity.significant_shift);

let severity = 'INFO';
if (atRisk.length || changedCampaigns.length || shifts.length) severity = 'WARNING';
if (cb.tripped || stats.mailboxes_by_tier.CRITICAL > 0 || (run.updateSummary && run.updateSummary.failed > 0)) severity = 'CRITICAL';

const modeLabel = {
  LIVE: ':satellite_antenna: LIVE',
  SANDBOX_PREVIEW: ':test_tube: SANDBOX (mock data)',
  DRY_RUN_PREVIEW: ':eyes: DRY RUN',
  UPDATES_DISABLED_PREVIEW: ':lock: UPDATES DISABLED',
  BLOCKED_CIRCUIT_BREAKER: ':octagonal_sign: BLOCKED (circuit breaker)',
  BLOCKED_CONFIG_INVALID: ':no_entry: BLOCKED (invalid config)',
  NOTHING_TO_UPDATE: ':white_check_mark: NO CHANGES',
}[run.updateSummary.mode] || run.updateSummary.mode;

const sevHeader = { INFO: ':white_check_mark: Outbound Pacing Run — All Clear', WARNING: ':warning: Outbound Pacing Run — Adjustments & Warnings', CRITICAL: ':rotating_light: Outbound Pacing Run — Critical Deliverability Alert' }[severity];

const blocks = [];
blocks.push({ type: 'header', text: { type: 'plain_text', text: sevHeader.slice(0, 150), emoji: true } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `*Run* \`${run.runId}\`  ·  *Mode* ${modeLabel}  ·  *Source* ${run.dataSource}  ·  *Trigger* ${run.trigger}  ·  ${run.evaluatedAt}` }] });

if (cb.tripped) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: truncate(`:octagonal_sign: *CIRCUIT BREAKER TRIPPED — all automated pacing changes frozen*\n${cb.reasons.map((r) => `• ${r}`).join('\n')}\n*Recommended:* ${cb.recommended_action}`) } });
}

blocks.push({
  type: 'section',
  fields: [
    { type: 'mrkdwn', text: `*Mailboxes evaluated*\n${stats.mailboxes_evaluated}` },
    { type: 'mrkdwn', text: `*At-risk mailboxes*\n${atRisk.length} (${stats.mailboxes_by_tier.CRITICAL} critical)` },
    { type: 'mrkdwn', text: `*Campaigns evaluated*\n${stats.campaigns_evaluated} (${stats.campaigns_skipped} skipped)` },
    { type: 'mrkdwn', text: `*Step gaps changed*\n${stats.step_gaps_compressed} compressed · ${stats.step_gaps_expanded} expanded` },
    { type: 'mrkdwn', text: `*Updates*\n${run.updateSummary.applied} applied · ${run.updateSummary.previewed} previewed · ${run.updateSummary.failed} failed` },
    { type: 'mrkdwn', text: `*Org bounce rate (7d)*\n${cb.org_bounce_rate_pct}% (breaker ${cfg.circuitBreaker.orgBounceRatePct}%)` },
  ],
});

blocks.push({ type: 'divider' });
if (atRisk.length) {
  const lines = atRisk.slice(0, maxItems).map((m) => `${tierIcon[m.tier]} \`${m.mailbox_id}\` *${m.tier}* · score ${m.health_score} · bounce ${m.bounce_rate_pct}% · spam ${m.spam_complaint_rate_pct}% · util ${m.volume_utilization_pct}% · ${m.sending_domain || 'n/a'}`);
  if (atRisk.length > maxItems) lines.push(`_+${atRisk.length - maxItems} more in the audit log_`);
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: truncate(`*:mailbox_with_mail: Mailbox health warnings*\n${lines.join('\n')}`) } });
} else {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*:mailbox_with_mail: Mailbox health*\nAll active mailboxes are HEALTHY.' } });
}

blocks.push({ type: 'divider' });
if (changedCampaigns.length) {
  const resultBy = Object.fromEntries((run.updateResults || []).map((r) => [r.campaign_id, r.status]));
  const parts = changedCampaigns.slice(0, maxItems).map((c) => {
    const rows = c.adjustments.filter((a) => a.delta_days !== 0).map((a) => `      ${dirIcon[a.direction]} Step ${a.from_step}→${a.to_step}: ${a.current_delay_days}d → *${a.proposed_delay_days}d* (${a.velocity_band})`);
    return `${tierIcon[c.health.tier]} *${c.campaign_id} · ${c.name}* — health ${c.health.tier}, status \`${resultBy[c.campaign_id] || c.decision}\`\n${rows.join('\n')}`;
  });
  if (changedCampaigns.length > maxItems) parts.push(`_+${changedCampaigns.length - maxItems} more campaigns in the audit log_`);
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: truncate(`*:hourglass_flowing_sand: Pacing adjustments*\n${parts.join('\n')}`) } });
} else {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*:hourglass_flowing_sand: Pacing adjustments*\nNo step-delay changes this run.' } });
}

if (shifts.length) {
  const lines = shifts.slice(0, maxItems).map((c) => `${c.velocity.shift_pct > 0 ? ':chart_with_upwards_trend:' : ':chart_with_downwards_trend:'} *${c.campaign_id}* velocity ${c.velocity.index} vs 30d baseline ${c.velocity.baseline_index_30d} (${c.velocity.shift_pct > 0 ? '+' : ''}${c.velocity.shift_pct}%) · band ${c.velocity.band}`);
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: truncate(`*:zap: Campaign velocity shifts*\n${lines.join('\n')}`) } });
}

const footer = run.updateSummary.mode === 'LIVE'
  ? 'Changes were written to the outbound platform. Review the audit log for per-campaign results.'
  : 'Preview only — no changes were written to the outbound platform.';
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `${footer}  ·  n8n-outbound-sequence-step-pacing-optimization-engine v${run.workflowVersion}` }] });

const fallbackText = `[${severity}] Outbound pacing run ${run.runId}: ${atRisk.length} at-risk mailboxes, ${changedCampaigns.length} campaigns with pacing changes, mode ${run.updateSummary.mode}.`;

const meetsSeverity = SEV_RANK[severity] >= SEV_RANK[cfg.alerts.minSeverity];
const dispatch = {
  severity,
  meetsMinSeverity: meetsSeverity,
  slack: gate.slackAlertsPermitted === true && meetsSeverity,
  webhook: gate.webhookAlertsPermitted === true && meetsSeverity,
};

const webhookEvent = {
  event: 'outbound.pacing.run_completed',
  run_id: run.runId,
  severity,
  mode: run.updateSummary.mode,
  data_source: run.dataSource,
  evaluated_at: run.evaluatedAt,
  circuit_breaker: { tripped: cb.tripped, reasons: cb.reasons, org_bounce_rate_pct: cb.org_bounce_rate_pct },
  stats,
  update_summary: run.updateSummary,
  mailbox_warnings: atRisk.map((m) => ({ mailbox_id: m.mailbox_id, tier: m.tier, health_score: m.health_score, bounce_rate_pct: m.bounce_rate_pct, spam_complaint_rate_pct: m.spam_complaint_rate_pct, sending_domain: m.sending_domain })),
  pacing_changes: changedCampaigns.map((c) => ({
    campaign_id: c.campaign_id,
    health_tier: c.health.tier,
    changes: c.adjustments.filter((a) => a.delta_days !== 0).map((a) => ({ from_step: a.from_step, to_step: a.to_step, from_days: a.current_delay_days, to_days: a.proposed_delay_days, direction: a.direction })),
  })),
  velocity_shifts: shifts.map((c) => ({ campaign_id: c.campaign_id, index: c.velocity.index, baseline: c.velocity.baseline_index_30d, shift_pct: c.velocity.shift_pct })),
};

return [{
  json: {
    ...run,
    alerts: {
      dispatch,
      slackPayload: { text: fallbackText, blocks: blocks.slice(0, 50) },
      webhookEvent,
    },
  },
}];

// =====================================================================
// Execution Summary & Audit
// One structured audit record per run: what was evaluated, what changed,
// what was sent, and why. Ship this item to a log store or warehouse.
// =====================================================================
const run = $('Build RevOps Alerts').first().json;

const dispatchStatus = (nodeName, wanted) => {
  if (!wanted) return 'NOT_SENT';
  try {
    if (!$(nodeName).isExecuted) return 'NOT_SENT';
    const j = $(nodeName).first().json || {};
    return j.error ? `FAILED: ${String(j.error.message || j.error).slice(0, 200)}` : 'SENT';
  } catch (e) {
    return 'UNKNOWN';
  }
};

const finishedAt = new Date().toISOString();
const durationMs = new Date(finishedAt).getTime() - new Date(run.startedAt).getTime();

const changes = run.campaigns.flatMap((c) => (c.adjustments || [])
  .filter((a) => a.delta_days !== 0)
  .map((a) => ({
    campaign_id: c.campaign_id,
    from_step: a.from_step,
    to_step: a.to_step,
    from_days: a.current_delay_days,
    to_days: a.proposed_delay_days,
    direction: a.direction,
    velocity_band: a.velocity_band,
    health_tier: c.health ? c.health.tier : null,
    decision: c.decision,
    write_status: ((run.updateResults || []).find((r) => r.campaign_id === c.campaign_id) || {}).status || 'NOT_SENT',
    reasons: a.reasons,
  })));

return [{
  json: {
    audit: {
      run_id: run.runId,
      workflow: run.workflow,
      workflow_version: run.workflowVersion,
      trigger: run.trigger,
      started_at: run.startedAt,
      finished_at: finishedAt,
      duration_ms: durationMs,
      data_source: run.dataSource,
      data_as_of: run.dataAsOf,
      safety: {
        mode: run.gate.mode,
        sandbox_mode: run.gate.sandboxMode,
        dry_run: run.gate.dryRun,
        live_mutations_permitted: run.gate.liveMutationsPermitted,
        delivery_mode: run.updateSummary.mode,
        circuit_breaker_tripped: run.circuitBreaker.tripped,
        circuit_breaker_reasons: run.circuitBreaker.reasons,
        gate_reasons: run.gate.reasons,
        config_warnings: run.gate.warnings,
        config_errors: run.gate.configErrors,
      },
      stats: run.stats,
      update_summary: run.updateSummary,
      alerts: {
        severity: run.alerts.dispatch.severity,
        slack: dispatchStatus('Post Slack Alert', run.alerts.dispatch.slack),
        webhook: dispatchStatus('Post Alert Webhook', run.alerts.dispatch.webhook),
      },
      mailbox_health: run.mailboxes.map((m) => ({ mailbox_id: m.mailbox_id, tier: m.tier, health_score: m.health_score, bounce_rate_pct: m.bounce_rate_pct, spam_complaint_rate_pct: m.spam_complaint_rate_pct, volume_utilization_pct: m.volume_utilization_pct })),
      campaign_decisions: run.campaigns.map((c) => ({ campaign_id: c.campaign_id, decision: c.decision, health_tier: c.health ? c.health.tier : null, velocity_band: c.velocity ? c.velocity.band : null, velocity_shift_pct: c.velocity ? c.velocity.shift_pct : null, notes: c.notes })),
      pacing_changes: changes,
      thresholds_snapshot: { thresholds: run.config.thresholds, pacing: run.config.pacing, velocity: run.config.velocity, health: run.config.health, circuit_breaker: run.config.circuitBreaker },
    },
  },
}];
